function balance(items: QuizQuestion[]): QuizQuestion[] {
  let choice = 0, comparison = 0, multi = 0;
  const pairs = [[0, 2], [1, 3], [0, 3], [1, 2], [2, 3], [0, 1]];
  return items.map((q) => {
    if (q.type === 'single_choice' || q.type === 'predict_output') {
      const options = [...q.options]; const correct = options.splice(q.answer, 1)[0]; const answer = choice++ % (options.length + 1); options.splice(answer, 0, correct); return { ...q, options, answer };
    }
    if (q.type === 'multi_select') {
      const [r1, r2, w1, w2] = q.options; const pos = pairs[multi++ % pairs.length]; const options: string[] = []; const wrong = [w1, w2];
      for (let i = 0; i < 4; i++) options.push(i === pos[0] ? r1 : i === pos[1] ? r2 : wrong.shift()!);
      return { ...q, options, answers: pos };
    }
    if (q.type === 'code_comparison' && comparison++ % 2) return { ...q, a: q.b, b: q.a, answer: q.answer === 0 ? 1 : 0 };
    return q;
  });
}

export const WORLD_13_QUIZ = balance([...direct, ...setQuestions]);
export const WORLD_13_BOSS_QUIZ = balance(boss);
